/**
 * Tenancy on PGlite (real Postgres in-process): RESTRICTIVE RLS generated by `tenantRlsSql`, the
 * `withTenant` helper, cross-tenant CRUD attacks, the tenancy audit and the session-SET lint.
 * Pooling/PgBouncer leak tests that need a real server live in test/integration.
 */
import { EventEmitter } from 'node:events'
import { PGlite } from '@electric-sql/pglite'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { PolicyDefinitionError } from '../src/errors.ts'
import {
  findSessionSet,
  InvalidTenantIdError,
  postgresRateLimitStore,
  rateLimitTableSql,
  relationKeyAudit,
  type TenantClient,
  TransactionAbortedError,
  tenancyAudit,
  tenancyRolesSql,
  tenantExpression,
  tenantRlsSql,
  withTenant,
} from '../src/postgres/index.ts'
import { TENANT_A, TENANT_B } from './fixtures.ts'

interface ShimClient extends TenantClient {
  query(text: string, values?: unknown[]): Promise<{ rows: Record<string, unknown>[] }>
}

/** A pg-Pool-shaped wrapper around one PGlite connection, recording releases. */
function pglitePool(db: PGlite) {
  const releases: (Error | boolean | undefined)[] = []
  let out = 0
  return {
    releases,
    checkedOut: () => out,
    pool: {
      async connect(): Promise<ShimClient> {
        out++
        return {
          query: (text: string, values?: unknown[]) =>
            db.query<Record<string, unknown>>(text, values),
          release: (error?: Error | boolean) => {
            out--
            releases.push(error)
          },
          on: () => undefined,
          off: () => undefined,
        }
      },
    },
  }
}

let db: PGlite
let p: ReturnType<typeof pglitePool>
const rows = async (sql: string, params: unknown[] = []) =>
  (await db.query<Record<string, unknown>>(sql, params)).rows

beforeAll(async () => {
  db = new PGlite()
  for (const s of tenancyRolesSql().up) await db.exec(s)
  await db.exec('CREATE SCHEMA app AUTHORIZATION app_owner')
  await db.exec('SET ROLE app_owner')
  await db.exec(
    'CREATE TABLE app.invoices (id serial PRIMARY KEY, tenant_id uuid NOT NULL, number text NOT NULL)',
  )
  for (const s of tenantRlsSql({ table: 'app.invoices', runtimeRole: 'app_user' }).up)
    await db.exec(s)
  await db.exec('GRANT USAGE ON SCHEMA app TO app_user')
  await db.exec('GRANT SELECT, INSERT, UPDATE, DELETE ON app.invoices TO app_user')
  await db.exec('GRANT USAGE ON SEQUENCE app.invoices_id_seq TO app_user')
  await db.exec('RESET ROLE')
  // Seed as the superuser (bypasses RLS), then become the runtime role for every test.
  await db.query(
    'INSERT INTO app.invoices (tenant_id, number) VALUES ($1, $2), ($1, $3), ($4, $5)',
    [TENANT_A, 'A-1', 'A-2', TENANT_B, 'B-1'],
  )
  await db.exec('SET ROLE app_user')
  p = pglitePool(db)
}, 60_000)

afterAll(async () => {
  await db.close()
})

describe('RESTRICTIVE RLS + withTenant', () => {
  it('an unscoped connection sees zero rows (fail closed), not an error', async () => {
    expect(await rows('SELECT * FROM app.invoices')).toEqual([])
  })

  it('withTenant sees only its own tenant, and the setting dies with the transaction', async () => {
    const a = await withTenant(
      p.pool,
      TENANT_A,
      async (c) => (await c.query('SELECT number FROM app.invoices ORDER BY number')).rows,
    )
    expect(a).toEqual([{ number: 'A-1' }, { number: 'A-2' }])
    const b = await withTenant(
      p.pool,
      TENANT_B.toUpperCase(),
      async (c) => (await c.query('SELECT number FROM app.invoices')).rows,
    )
    expect(b).toEqual([{ number: 'B-1' }])
    expect(await rows("SELECT current_setting('app.tenant_id', true) AS s")).toEqual([{ s: '' }])
    expect(await rows('SELECT * FROM app.invoices')).toEqual([])
    expect(p.checkedOut()).toBe(0)
  })

  it('cross-tenant CRUD is impossible: read, insert, update (move), delete', async () => {
    await withTenant(p.pool, TENANT_A, async (c) => {
      // Read by predicate on the other tenant: nothing.
      expect(
        (await c.query('SELECT * FROM app.invoices WHERE tenant_id = $1', [TENANT_B])).rows,
      ).toEqual([])
      // Update and delete across tenants affect nothing.
      await c.query("UPDATE app.invoices SET number = 'pwned' WHERE tenant_id = $1", [TENANT_B])
      await c.query('DELETE FROM app.invoices WHERE tenant_id = $1', [TENANT_B])
    })
    await expect(
      withTenant(p.pool, TENANT_A, (c) =>
        c.query("INSERT INTO app.invoices (tenant_id, number) VALUES ($1, 'evil')", [TENANT_B]),
      ),
    ).rejects.toThrow(/row-level security/)
    await expect(
      withTenant(p.pool, TENANT_A, (c) =>
        c.query('UPDATE app.invoices SET tenant_id = $1', [TENANT_B]),
      ),
    ).rejects.toThrow(/row-level security/)
    const b = await withTenant(
      p.pool,
      TENANT_B,
      async (c) => (await c.query('SELECT number FROM app.invoices')).rows,
    )
    expect(b).toEqual([{ number: 'B-1' }])
  })

  it('a later "admin" permissive policy cannot widen access across tenants', async () => {
    await db.exec('RESET ROLE')
    await db.exec(
      'CREATE POLICY admins_see_all ON app.invoices AS PERMISSIVE FOR SELECT TO app_user USING (true)',
    )
    await db.exec('SET ROLE app_user')
    try {
      const a = await withTenant(
        p.pool,
        TENANT_A,
        async (c) => (await c.query('SELECT count(*)::int AS n FROM app.invoices')).rows,
      )
      expect(a).toEqual([{ n: 2 }])
    } finally {
      await db.exec('RESET ROLE')
      await db.exec('DROP POLICY admins_see_all ON app.invoices')
      await db.exec('SET ROLE app_user')
    }
  })

  it('FORCE applies RLS to the table owner too', async () => {
    await db.exec('RESET ROLE')
    await db.exec('SET ROLE app_owner')
    try {
      expect(await rows('SELECT * FROM app.invoices')).toEqual([])
    } finally {
      await db.exec('RESET ROLE')
      await db.exec('SET ROLE app_user')
    }
  })

  it('rolls back on error, re-throws the original error and releases the client', async () => {
    const boom = new Error('boom')
    await expect(
      withTenant(p.pool, TENANT_A, async (c) => {
        await c.query("INSERT INTO app.invoices (tenant_id, number) VALUES ($1, 'rolled-back')", [
          TENANT_A,
        ])
        throw boom
      }),
    ).rejects.toBe(boom)
    const a = await withTenant(
      p.pool,
      TENANT_A,
      async (c) => (await c.query("SELECT * FROM app.invoices WHERE number = 'rolled-back'")).rows,
    )
    expect(a).toEqual([])
    expect(p.releases.at(-2)).toBeUndefined() // a clean rollback returns the client to the pool
  })

  it('validates the tenant id before checking out a connection', async () => {
    const before = p.releases.length
    for (const bad of ["x' OR 1=1 --", '', 'not-a-uuid', `${TENANT_A} `]) {
      await expect(withTenant(p.pool, bad, async () => 1)).rejects.toBeInstanceOf(
        InvalidTenantIdError,
      )
    }
    await expect(
      withTenant(p.pool, TENANT_A, async () => 1, { setting: "x'); DROP" }),
    ).rejects.toThrow(TypeError)
    expect(p.releases.length).toBe(before)
    expect(new InvalidTenantIdError().message).not.toContain("'")
  })
})

describe('withTenant: broken connections are destroyed, never re-pooled', () => {
  class FakeClient extends EventEmitter implements TenantClient {
    released: Error | boolean | undefined = 'not released' as never
    readonly failOn: (sql: string) => boolean
    constructor(failOn: (sql: string) => boolean) {
      super()
      this.failOn = failOn
    }
    async query(sql: string) {
      if (this.failOn(sql)) throw new Error(`failed: ${sql}`)
      return { rows: [] }
    }
    release(error?: Error | boolean) {
      this.released = error
    }
  }
  const poolOf = (client: FakeClient) => ({ connect: async () => client })

  it('when BEGIN fails', async () => {
    const c = new FakeClient((s) => s === 'BEGIN')
    await expect(withTenant(poolOf(c), TENANT_A, async () => 1)).rejects.toThrow('failed: BEGIN')
    expect(c.released).toBeInstanceOf(Error)
  })

  it('when ROLLBACK fails after an error', async () => {
    const c = new FakeClient((s) => s === 'ROLLBACK')
    await expect(
      withTenant(poolOf(c), TENANT_A, async () => Promise.reject(new Error('work failed'))),
    ).rejects.toThrow('work failed')
    expect(c.released).toBeInstanceOf(Error)
  })

  it('when the backend dies mid-transaction (client "error" event), without crashing the process', async () => {
    const c = new FakeClient(() => false)
    await withTenant(poolOf(c), TENANT_A, async () => {
      c.emit('error', new Error('terminating connection due to administrator command'))
    })
    expect(c.released).toBeInstanceOf(Error)
    expect(c.listenerCount('error')).toBe(0)
  })

  it('non-Error rejections are wrapped', async () => {
    const c = new FakeClient(() => false)
    c.query = async (sql: string) => {
      if (sql === 'BEGIN') throw 'string failure'
      return { rows: [] }
    }
    await expect(withTenant(poolOf(c), TENANT_A, async () => 1)).rejects.toBe('string failure')
    expect(c.released).toBeInstanceOf(Error)
  })
})

describe('migration SQL generators', () => {
  it('tenantRlsSql follows ADR-0007', () => {
    const { up, down } = tenantRlsSql({ table: 'invoices' })
    expect(up).toEqual([
      'ALTER TABLE "invoices" ENABLE ROW LEVEL SECURITY',
      'ALTER TABLE "invoices" FORCE ROW LEVEL SECURITY',
      `CREATE POLICY "invoices_tenant_isolation" ON "invoices" AS RESTRICTIVE FOR ALL USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)`,
    ])
    expect(down).toEqual([
      'DROP POLICY IF EXISTS "invoices_tenant_isolation" ON "invoices"',
      'ALTER TABLE "invoices" NO FORCE ROW LEVEL SECURITY',
      'ALTER TABLE "invoices" DISABLE ROW LEVEL SECURITY',
    ])
    expect(
      tenantRlsSql({ table: 'a.t', column: 'org_id', setting: 'my.org', runtimeRole: 'web' }).up.at(
        -1,
      ),
    ).toBe(
      'CREATE POLICY "t_runtime_access" ON "a"."t" AS PERMISSIVE FOR ALL TO "web" USING (true) WITH CHECK (true)',
    )
  })

  it('rejects unsafe identifiers and settings', () => {
    expect(() => tenantRlsSql({ table: 'x"; DROP TABLE y; --' })).toThrow(PolicyDefinitionError)
    expect(() => tenantRlsSql({ table: 't', column: 'a b' })).toThrow(PolicyDefinitionError)
    expect(() => tenantRlsSql({ table: 't', runtimeRole: 'r; x' })).toThrow(PolicyDefinitionError)
    expect(() => tenantExpression("app.x', true); DROP --")).toThrow(TypeError)
  })

  it('tenancyRolesSql never includes passwords or bypass rights', () => {
    const { up, down } = tenancyRolesSql({ owner: 'o', runtime: 'r' })
    expect(up.join(' ')).toMatch(/NOBYPASSRLS/)
    expect(up.join(' ')).not.toMatch(/PASSWORD|SUPERUSER(?! )|\bBYPASSRLS/)
    expect(down).toEqual(['DROP ROLE IF EXISTS "r"', 'DROP ROLE IF EXISTS "o"'])
  })
})

describe('tenancyAudit', () => {
  const asSuper = async <T>(fn: () => Promise<T>) => {
    await db.exec('RESET ROLE')
    try {
      return await fn()
    } finally {
      await db.exec('SET ROLE app_user')
    }
  }

  it('reports nothing for a protected database, as the runtime role', async () => {
    expect(await tenancyAudit(db)).toEqual([])
  })

  it('finds every class of mistake', async () => {
    await asSuper(async () => {
      await db.exec(`
        CREATE TABLE public.open_t (id int, tenant_id uuid);
        CREATE TABLE public.unforced (id int, tenant_id uuid);
        ALTER TABLE public.unforced ENABLE ROW LEVEL SECURITY;
        CREATE POLICY p ON public.unforced AS PERMISSIVE FOR ALL USING (true);
        CREATE TABLE public.select_only (id int, tenant_id uuid);
        ALTER TABLE public.select_only ENABLE ROW LEVEL SECURITY;
        ALTER TABLE public.select_only FORCE ROW LEVEL SECURITY;
        CREATE POLICY r ON public.select_only AS RESTRICTIVE FOR SELECT USING (true);
        CREATE VIEW public.leaky AS SELECT * FROM app.invoices;
        CREATE VIEW public.safe WITH (security_invoker = true) AS SELECT * FROM app.invoices;
        CREATE MATERIALIZED VIEW public.snap AS SELECT * FROM app.invoices;
        CREATE FUNCTION public.definer() RETURNS int LANGUAGE sql SECURITY DEFINER AS 'SELECT 1';
      `)
    })
    const codes = (await tenancyAudit(db)).map((f) => `${f.severity}:${f.code}:${f.object}`)
    expect(codes).toEqual(
      expect.arrayContaining([
        'error:RLS_DISABLED:public.open_t',
        'error:NO_RESTRICTIVE_POLICY:public.open_t',
        'error:RLS_NOT_FORCED:public.unforced',
        'error:NO_RESTRICTIVE_POLICY:public.unforced',
        'error:NO_RESTRICTIVE_POLICY:public.select_only',
        'error:DEFINER_VIEW:public.leaky',
        'error:DEFINER_VIEW:public.snap',
        'warning:SECURITY_DEFINER_FUNCTION:public.definer',
      ]),
    )
    expect(codes.some((c) => c.includes('public.safe'))).toBe(false)
    expect(codes.at(-1)?.startsWith('warning')).toBe(true)

    // The superuser bypasses RLS; the audit says so. Owning a table is flagged too.
    const asRoot = await asSuper(() => tenancyAudit(db))
    expect(asRoot.map((f) => f.code)).toContain('RUNTIME_ROLE_BYPASSES_RLS')
    await db.exec('RESET ROLE')
    await db.exec('SET ROLE app_owner')
    const asOwner = await tenancyAudit(db)
    await db.exec('RESET ROLE')
    await db.exec('SET ROLE app_user')
    expect(asOwner.map((f) => `${f.code}:${f.object}`)).toContain(
      'RUNTIME_ROLE_OWNS_TABLE:app.invoices',
    )

    await asSuper(() =>
      db.exec(
        'DROP TABLE public.open_t, public.unforced, public.select_only; DROP VIEW public.leaky, public.safe; DROP MATERIALIZED VIEW public.snap; DROP FUNCTION public.definer()',
      ),
    )
    expect(await tenancyAudit(db)).toEqual([])
  })

  it('validates the column name', async () => {
    await expect(tenancyAudit(db, { column: 'x; drop' })).rejects.toThrow(TypeError)
    await expect(tenancyAudit(db, { setting: "x'; drop" })).rejects.toThrow(TypeError)
  })

  it('sees ownership and RLS bypass through role membership', async () => {
    await asSuper(() =>
      db.exec('CREATE ROLE sv_bypass NOLOGIN BYPASSRLS; GRANT app_owner, sv_bypass TO app_user'),
    )
    try {
      const codes = (await tenancyAudit(db)).map((f) => `${f.code}:${f.object}`)
      expect(codes).toContain('RUNTIME_ROLE_OWNS_TABLE:app.invoices')
      expect(codes).toContain('RUNTIME_ROLE_BYPASSES_RLS:app_user')
    } finally {
      await asSuper(() => db.exec('REVOKE app_owner, sv_bypass FROM app_user; DROP ROLE sv_bypass'))
    }
    expect(await tenancyAudit(db)).toEqual([])
  })

  it('only a RESTRICTIVE FOR ALL policy for every role that reads the tenant setting counts', async () => {
    await asSuper(() =>
      db.exec(`
        CREATE TABLE public.restr_true (id int, tenant_id uuid);
        ALTER TABLE public.restr_true ENABLE ROW LEVEL SECURITY;
        ALTER TABLE public.restr_true FORCE ROW LEVEL SECURITY;
        CREATE POLICY p ON public.restr_true AS RESTRICTIVE FOR ALL USING (true) WITH CHECK (true);
        CREATE TABLE public.to_other (id int, tenant_id uuid);
        ALTER TABLE public.to_other ENABLE ROW LEVEL SECURITY;
        ALTER TABLE public.to_other FORCE ROW LEVEL SECURITY;
        CREATE POLICY p ON public.to_other AS RESTRICTIVE FOR ALL TO app_owner
          USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
        CREATE TABLE public.weak_check (id int, tenant_id uuid);
        ALTER TABLE public.weak_check ENABLE ROW LEVEL SECURITY;
        ALTER TABLE public.weak_check FORCE ROW LEVEL SECURITY;
        CREATE POLICY p ON public.weak_check AS RESTRICTIVE FOR ALL
          USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
          WITH CHECK (true);
        CREATE TABLE public.using_only (id int, tenant_id uuid);
        ALTER TABLE public.using_only ENABLE ROW LEVEL SECURITY;
        ALTER TABLE public.using_only FORCE ROW LEVEL SECURITY;
        CREATE POLICY p ON public.using_only AS RESTRICTIVE FOR ALL
          USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
      `),
    )
    try {
      const codes = (await tenancyAudit(db)).map((f) => `${f.code}:${f.object}`)
      expect(codes).toEqual(
        expect.arrayContaining([
          'NO_RESTRICTIVE_POLICY:public.restr_true',
          'NO_RESTRICTIVE_POLICY:public.to_other',
          'NO_RESTRICTIVE_POLICY:public.weak_check',
        ]),
      )
      // USING without WITH CHECK: Postgres applies USING to writes too, so it is protected.
      expect(codes).not.toContain('NO_RESTRICTIVE_POLICY:public.using_only')
    } finally {
      await asSuper(() =>
        db.exec(
          'DROP TABLE public.restr_true, public.to_other, public.weak_check, public.using_only',
        ),
      )
    }
  })

  it('flags a role- or database-level default for the tenant setting', async () => {
    await asSuper(() => db.exec(`ALTER ROLE app_user SET app.tenant_id = '${TENANT_A}'`))
    try {
      const findings = await tenancyAudit(db)
      expect(findings.map((f) => `${f.code}:${f.object}`)).toContain(
        'TENANT_SETTING_DEFAULT:app_user',
      )
    } finally {
      await asSuper(() => db.exec('ALTER ROLE app_user RESET app.tenant_id'))
    }
    expect(await tenancyAudit(db)).toEqual([])
  })
})

describe('withTenant: a swallowed statement error is not reported as a commit', () => {
  const fakePool = (commitTag: string | undefined) => {
    const released: unknown[] = []
    return {
      released,
      pool: {
        connect: async (): Promise<TenantClient> => ({
          query: async (text: string) =>
            text === 'COMMIT' && commitTag !== undefined ? { command: commitTag } : { rows: [] },
          release: (e?: Error | boolean) => {
            released.push(e)
          },
          on: () => undefined,
          off: () => undefined,
        }),
      },
    }
  }

  it('COMMIT answered with ROLLBACK rejects with TransactionAbortedError', async () => {
    const f = fakePool('ROLLBACK')
    await expect(withTenant(f.pool, TENANT_A, async () => 'saved?')).rejects.toBeInstanceOf(
      TransactionAbortedError,
    )
    expect(f.released).toEqual([undefined])
  })

  it('a real COMMIT, or a driver without command tags, resolves', async () => {
    expect(await withTenant(fakePool('COMMIT').pool, TENANT_A, async () => 1)).toBe(1)
    expect(await withTenant(fakePool(undefined).pool, TENANT_A, async () => 2)).toBe(2)
  })
})

describe('relationKeyAudit', () => {
  it('requires a unique key on the relation target; reports missing tables', async () => {
    await db.exec('RESET ROLE')
    try {
      await db.exec(`
        CREATE TABLE public.rk_customers (id uuid PRIMARY KEY, code text);
        CREATE TABLE public.rk_dupes (code text);
        CREATE UNIQUE INDEX rk_partial ON public.rk_dupes (code) WHERE code <> '';
      `)
      const columns = { id: { column: 'id', type: 'uuid' } } as const
      const schema = (table: string, targetKey: string) => ({
        table: 'rk_invoices',
        columns,
        relations: { r: { table, foreignKey: 'r_id', targetKey, columns } },
      })
      expect(await relationKeyAudit(db, [schema('public.rk_customers', 'id')])).toEqual([])
      const findings = await relationKeyAudit(db, [
        schema('public.rk_customers', 'code'),
        schema('public.rk_dupes', 'code'),
        schema('public.rk_missing', 'id'),
        schema('public.rk_missing', 'id'),
        { table: 'x', columns },
      ])
      expect(findings.map((f) => `${f.code}:${f.object}`)).toEqual([
        'RELATION_KEY_NOT_UNIQUE:public.rk_customers.code',
        'RELATION_KEY_NOT_UNIQUE:public.rk_dupes.code',
        'RELATION_TABLE_MISSING:public.rk_missing.id',
      ])
      await expect(relationKeyAudit(db, [schema('a; drop', 'id')])).rejects.toThrow(
        PolicyDefinitionError,
      )
    } finally {
      await db.exec('DROP TABLE IF EXISTS public.rk_customers, public.rk_dupes')
      await db.exec('SET ROLE app_user')
    }
  })
})

describe('findSessionSet (lint for ADR-0007 rule 3)', () => {
  it('flags session-level SET and set_config(..., false), warns on SET LOCAL', () => {
    const sql = [
      "SELECT set_config('app.tenant_id', $1, true); -- fine",
      "SET app.tenant_id = 'x';",
      'set session app.tenant_id to $1;',
      "SET LOCAL app.tenant_id = '0190';",
      "SELECT set_config('app.tenant_id', $1, false);",
      "SELECT set_config( 'app.tenant_id' , lower($1) , is_local );",
      '-- SET app.tenant_id = 1 (commented out)',
      '/* SET app.tenant_id = 2 */',
      "SELECT set_config('app.other', $1, false);",
      'SELECT set_config($1, $2, false);',
      'SET search_path = app;',
    ].join('\n')
    expect(findSessionSet(sql).map((f) => `${f.line}:${f.severity}:${f.code}`)).toEqual([
      '2:error:SESSION_SET',
      '3:error:SESSION_SET',
      '4:warning:SET_LOCAL',
      '5:error:SESSION_SET_CONFIG',
      '6:error:SESSION_SET_CONFIG',
    ])
  })

  it('flags persistent defaults, RESET and quoted setting names', () => {
    const sql = [
      "ALTER ROLE app_user SET app.tenant_id = 'x';",
      "ALTER DATABASE d SET app.tenant_id TO 'x';",
      'SET "app"."tenant_id" = 1;',
      'SET "app.tenant_id" TO \'x\';',
      'RESET app.tenant_id;',
      'ALTER ROLE r RESET app.tenant_id;',
      'SET LOCAL "app" . tenant_id = \'x\';',
      'ALTER USER u IN DATABASE d SET "app"."tenant_id" = \'x\';',
      'SET app.tenant_idx = 1;',
    ].join('\n')
    expect(findSessionSet(sql).map((f) => `${f.line}:${f.severity}:${f.code}`)).toEqual([
      '1:error:PERSISTENT_SET',
      '2:error:PERSISTENT_SET',
      '3:error:SESSION_SET',
      '4:error:SESSION_SET',
      '5:warning:SESSION_RESET',
      '7:warning:SET_LOCAL',
      '8:error:PERSISTENT_SET',
    ])
  })

  it('supports a custom setting name and ignores unbalanced calls', () => {
    expect(findSessionSet('SET my.org = 1', 'my.org')).toHaveLength(1)
    expect(findSessionSet("SELECT set_config('app.tenant_id', $1, false")).toEqual([])
    expect(findSessionSet("SELECT set_config('app.tenant_id', 'a,b)', false)")).toHaveLength(1)
  })
})

describe('postgresRateLimitStore', () => {
  it('counts atomically per key, resets after the window and prunes', async () => {
    await db.exec('RESET ROLE')
    try {
      await db.exec(rateLimitTableSql())
      const store = postgresRateLimitStore(db)
      expect((await store.hit('k', 60_000)).count).toBe(1)
      const second = await store.hit('k', 60_000)
      expect(second.count).toBe(2)
      expect(second.resetInMs).toBeGreaterThan(50_000)
      expect((await store.hit('other', 60_000)).count).toBe(1)
      await db.exec(
        "UPDATE strutvane_rate_limits SET reset_at = now() - interval '1 second' WHERE key = 'k'",
      )
      expect((await store.hit('k', 60_000)).count).toBe(1)
      await db.exec("UPDATE strutvane_rate_limits SET reset_at = now() - interval '1 second'")
      expect(await store.prune()).toBe(2)
      expect(() => rateLimitTableSql({ table: 'x; drop' })).toThrow(PolicyDefinitionError)
      const broken = postgresRateLimitStore({ query: async () => ({ rows: [] }) })
      await expect(broken.hit('k', 1)).rejects.toThrow(/no row/)
      expect(await postgresRateLimitStore({ query: async () => ({ rows: [] }) }).prune()).toBe(0)
    } finally {
      await db.exec('SET ROLE app_user')
    }
  })
})
